"use strict";const e=require("./request.js");exports.addFavorite=function(r){return e.post(`/recipes/favorites/${encodeURIComponent(r)}`)},exports.fetchFavorites=function(){return e.get("/recipes/favorites").then((r=>(Array.isArray(r)?r:[]).map((r=>({...r,image:r.image?e.resolveAssetUrl(r.image):null})))))},exports.removeFavorite=function(r){return e.del(`/recipes/favorites/${encodeURIComponent(r)}`)};
